#!/usr/bin/env python3
"""Add ~40 more AP Biology questions to reach ~300."""

import pathlib, re

FILE = pathlib.Path(__file__).resolve().parent.parent / "src" / "data" / "exit-quizzes" / "ap-biology.ts"

content = FILE.read_text()
# Find current max ID
ids = re.findall(r"bio-q(\d+)", content)
n = max(int(x) for x in ids) + 1

NEW_QS = []

def q(id_num, slug, cat, question, opts, correct, explanation):
    o = "[" + ", ".join(f"'{o}'" for o in opts) + "]"
    NEW_QS.append(
        f"  {{ id: 'bio-q{id_num}', topicSlug: '{slug}', category: '{cat}', "
        f"question: '{question}', options: {o}, correctIndex: {correct}, "
        f"explanation: '{explanation}' }},"
    )

# ═══════════ Additional Chemistry of Life ═══════════
q(n, 'ap-bio-chemistry-of-life', 'Chemistry of Life', 'Noncompetitive inhibitors bind to the:', ['Active site', 'Substrate', 'Allosteric site on the enzyme', 'Product'], 2, 'Noncompetitive inhibitors bind a site other than the active site, changing enzyme shape.'); n+=1
q(n, 'ap-bio-chemistry-of-life', 'Chemistry of Life', 'Glycogen is the storage polysaccharide in:', ['Plants', 'Animals', 'Bacteria', 'Fungi only'], 1, 'Animals store glucose as glycogen, mainly in liver and muscle cells.'); n+=1
q(n, 'ap-bio-chemistry-of-life', 'Chemistry of Life', 'An acid is a substance that:', ['Accepts protons', 'Donates protons (H+) in solution', 'Has a pH above 7', 'Is always a solid'], 1, 'Acids donate H+ ions, lowering the pH of a solution.'); n+=1

# ═══════════ Additional Cell Structure ═══════════
q(n, 'ap-bio-cell-structure-function', 'Cell Structure', 'The Golgi apparatus modifies, sorts, and ships:', ['DNA', 'Proteins and lipids', 'Chromosomes', 'Mitochondria'], 1, 'The Golgi processes and packages proteins for secretion or use within the cell.'); n+=1
q(n, 'ap-bio-cell-structure-function', 'Cell Structure', 'Which organelle is sometimes called the powerhouse of the cell?', ['Chloroplast', 'Nucleus', 'Mitochondrion', 'Ribosome'], 2, 'Mitochondria generate most of the ATP used by the cell.'); n+=1

# ═══════════ Additional Membrane Transport ═══════════
q(n, 'ap-bio-membrane-transport', 'Membrane Transport', 'Active transport requires:', ['No energy', 'ATP energy to move against the gradient', 'Osmosis', 'Only diffusion'], 1, 'Active transport uses energy to pump molecules against their concentration gradient.'); n+=1
q(n, 'ap-bio-membrane-transport', 'Membrane Transport', 'Turgor pressure in plant cells is maintained by:', ['The cell wall resisting water influx', 'Lack of a vacuole', 'Loss of water', 'Plasmolysis'], 0, 'The rigid cell wall pushes back against water entering by osmosis, creating turgor.'); n+=1

# ═══════════ Additional Cellular Energetics ═══════════
q(n, 'ap-bio-cellular-energetics', 'Cellular Energetics', 'The citric acid cycle occurs in the:', ['Cytoplasm', 'Mitochondrial matrix', 'Inner membrane', 'Nucleus'], 1, 'The Krebs/citric acid cycle takes place in the mitochondrial matrix.'); n+=1
q(n, 'ap-bio-cellular-energetics', 'Cellular Energetics', 'Oxidative phosphorylation produces the most ATP via:', ['Glycolysis', 'The electron transport chain and chemiosmosis', 'Fermentation', 'The Krebs cycle alone'], 1, 'Most ATP is generated by electron transport coupled with chemiosmosis.'); n+=1

# ═══════════ Additional Photosynthesis ═══════════
q(n, 'ap-bio-photosynthesis', 'Photosynthesis', 'Chlorophyll a absorbs light most effectively in the:', ['Green wavelengths', 'Blue-violet and red wavelengths', 'Yellow wavelengths only', 'Infrared range'], 1, 'Chlorophyll a has absorption peaks in blue-violet (~430 nm) and red (~662 nm).'); n+=1
q(n, 'ap-bio-photosynthesis', 'Photosynthesis', 'The stroma of the chloroplast is where:', ['Light reactions occur', 'The Calvin cycle occurs', 'Water is split', 'ATP synthase is absent'], 1, 'The Calvin cycle takes place in the stroma using ATP and NADPH from light reactions.'); n+=1

# ═══════════ Additional Cell Cycle / Meiosis ═══════════
q(n, 'ap-bio-cell-cycle-mitosis', 'Cell Cycle', 'During S phase of the cell cycle:', ['Cells divide', 'DNA is replicated', 'Chromosomes condense', 'Cytokinesis occurs'], 1, 'S (synthesis) phase is when DNA replication occurs.'); n+=1
q(n, 'ap-bio-meiosis', 'Meiosis', 'Independent assortment occurs because:', ['All chromosomes are identical', 'Homologous pairs line up randomly at the metaphase plate', 'Crossing over is impossible', 'Sister chromatids are linked'], 1, 'Random orientation of homologs at metaphase I gives independent assortment.'); n+=1

# ═══════════ Additional Molecular Genetics ═══════════
q(n, 'ap-bio-molecular-genetics', 'Molecular Genetics', 'The start codon AUG codes for:', ['Stop signal', 'Methionine', 'Leucine', 'Glycine'], 1, 'AUG is the universal start codon and codes for methionine.'); n+=1
q(n, 'ap-bio-molecular-genetics', 'Molecular Genetics', 'A nonsense mutation:', ['Changes one amino acid to another', 'Creates a premature stop codon', 'Has no effect', 'Adds bases'], 1, 'Nonsense mutations produce a stop codon, truncating the protein.'); n+=1
q(n, 'ap-bio-molecular-genetics', 'Molecular Genetics', 'DNA ligase functions to:', ['Unwind the double helix', 'Join Okazaki fragments and seal nicks in the DNA backbone', 'Add RNA primers', 'Proofread new DNA'], 1, 'Ligase seals gaps between Okazaki fragments on the lagging strand.'); n+=1

# ═══════════ Additional Gene Regulation ═══════════
q(n, 'ap-bio-gene-regulation', 'Gene Regulation', 'The lac operon is activated when:', ['Glucose is present', 'Lactose is present and glucose is absent', 'Only lactose is absent', 'The repressor is always bound'], 1, 'Lactose acts as an inducer, removing the repressor; low glucose allows CAP activation.'); n+=1
q(n, 'ap-bio-gene-regulation', 'Gene Regulation', 'Epigenetics involves heritable changes in gene expression without:', ['Protein folding', 'Changes to the DNA sequence', 'RNA transcription', 'Cell division'], 1, 'Epigenetic modifications (methylation, acetylation) alter expression without changing DNA sequence.'); n+=1

# ═══════════ Additional Cell Communication ═══════════
q(n, 'ap-bio-cell-communication', 'Cell Communication', 'Ligand refers to:', ['A type of lipid', 'A signaling molecule that binds to a receptor', 'An enzyme', 'A structural protein'], 1, 'Ligands are molecules (hormones, neurotransmitters) that bind specific receptors.'); n+=1
q(n, 'ap-bio-cell-communication', 'Cell Communication', 'Negative feedback in signaling:', ['Amplifies the original signal', 'Reduces or stops the signal after a response', 'Has no regulatory role', 'Only occurs in the brain'], 1, 'Negative feedback loops dampen a response once it reaches an appropriate level.'); n+=1

# ═══════════ Additional Genetics ═══════════
q(n, 'ap-bio-mendelian-genetics', 'Genetics', 'In a monohybrid cross Aa × Aa, the expected phenotype ratio is:', ['1:1', '3:1', '1:2:1', '9:3:3:1'], 1, 'A 3:1 dominant-to-recessive ratio is expected for a monohybrid cross.'); n+=1
q(n, 'ap-bio-mendelian-genetics', 'Genetics', 'Genetic drift has the greatest effect on:', ['Large populations', 'Small populations', 'All populations equally', 'Only marine organisms'], 1, 'Random changes in allele frequency are most impactful in small populations.'); n+=1

# ═══════════ Additional Evolution ═══════════
q(n, 'ap-bio-natural-selection', 'Evolution', 'Coevolution occurs when:', ['One species evolves and another does not change', 'Two or more species reciprocally influence each others evolution', 'Evolution stops in both species', 'Only predators evolve'], 1, 'Coevolution is the reciprocal evolutionary change between interacting species.'); n+=1
q(n, 'ap-bio-evolution-evidence', 'Evolution', 'Homologous structures suggest:', ['Convergent evolution', 'Common ancestry (divergent evolution)', 'No evolutionary relationship', 'Only functional similarity'], 1, 'Similar bone structures in vertebrate limbs indicate shared ancestry.'); n+=1

# ═══════════ Additional Ecology ═══════════
q(n, 'ap-bio-ecology-energy-flow', 'Ecology', 'Trophic levels describe:', ['The physical location of organisms', 'Feeding positions in a food chain', 'Water depth', 'Soil layers'], 1, 'Each trophic level represents a step in the transfer of energy.'); n+=1
q(n, 'ap-bio-ecology-interactions', 'Ecology', 'Invasive species often succeed because they:', ['Have many local predators', 'Lack natural predators in the new environment', 'Cannot compete well', 'Only eat native plants'], 1, 'Without predators, diseases, or competitors from their native range, invasives thrive.'); n+=1
q(n, 'ap-bio-ecology-interactions', 'Ecology', 'Mutualism benefits:', ['Only one species', 'Both interacting species', 'Neither species', 'The predator only'], 1, 'In mutualism, both partners benefit from the interaction.'); n+=1
q(n, 'ap-bio-population-ecology', 'Population Ecology', 'Density-dependent factors include:', ['Earthquakes and floods', 'Disease, competition, and predation', 'Volcanic eruptions', 'Droughts only'], 1, 'Density-dependent factors intensify as population density increases.'); n+=1

# ═══════════ Additional Biotechnology ═══════════
q(n, 'ap-bio-biotechnology', 'Biotechnology', 'Restriction enzymes cut DNA at:', ['Random locations', 'Specific recognition sequences', 'Only the ends of chromosomes', 'RNA sequences only'], 1, 'Restriction enzymes recognize and cut specific palindromic DNA sequences.'); n+=1
q(n, 'ap-bio-biotechnology', 'Biotechnology', 'Cloning involves:', ['Sexual reproduction', 'Creating a genetically identical copy of an organism or gene', 'Random mutagenesis', 'Only bacterial conjugation'], 1, 'Cloning produces genetic duplicates, whether of genes, cells, or whole organisms.'); n+=1

# ═══════════ Additional Scientific Practices ═══════════
q(n, 'ap-bio-experimental-design', 'Scientific Practices', 'A control group in an experiment:', ['Receives the treatment', 'Does not receive the treatment for comparison', 'Is always larger', 'Uses different organisms'], 1, 'The control group provides a baseline for comparing experimental results.'); n+=1
q(n, 'ap-bio-experimental-design', 'Scientific Practices', 'Correlation does not imply:', ['Association', 'Causation', 'Data collection', 'Observation'], 1, 'A correlation between variables does not prove one causes the other.'); n+=1

# ═══════════ Additional Immune System ═══════════
q(n, 'ap-bio-immune-system', 'Physiology', 'B cells produce:', ['Cytotoxic granules', 'Antibodies', 'Histamines only', 'Red blood cells'], 1, 'Activated B cells (plasma cells) secrete antibodies.'); n+=1
q(n, 'ap-bio-immune-system', 'Physiology', 'Vaccines work by:', ['Curing active infections', 'Stimulating immune memory without causing disease', 'Replacing white blood cells', 'Only treating bacterial infections'], 1, 'Vaccines expose the immune system to antigens, creating memory cells.'); n+=1
q(n, 'ap-bio-immune-system', 'Physiology', 'Natural killer (NK) cells are part of:', ['Adaptive immunity', 'Innate immunity', 'The complement system only', 'The endocrine system'], 1, 'NK cells are innate immune cells that destroy virus-infected and tumor cells.'); n+=1
q(n, 'ap-bio-immune-system', 'Physiology', 'Fever helps fight infection by:', ['Cooling the body', 'Increasing enzyme activity and inhibiting pathogen growth', 'Stopping all immune responses', 'Reducing blood flow'], 1, 'Elevated body temperature enhances immune function and slows microbial growth.'); n+=1
q(n, 'ap-bio-immune-system', 'Physiology', 'Histamine is released by mast cells and causes:', ['Vasoconstriction', 'Vasodilation and increased permeability', 'Blood clotting', 'Antibody production'], 1, 'Histamine promotes blood flow and allows immune cells to reach infected tissue.'); n+=1

marker = "\n]\n\nexport function generateExitQuiz"
if marker not in content:
    raise SystemExit("Could not find insertion marker in ap-biology.ts")

insert_block = "\n" + "\n".join(NEW_QS) + "\n"
new_content = content.replace(marker, insert_block + marker)
FILE.write_text(new_content)

count = len(re.findall(r"correctIndex:", new_content))
print(f"✅ AP Biology pool now has {count} questions total")
